```cpp
std::pair<int, Json::Value> OandaAPI::fetchInstruments() {
    std::string url = OANDA_URL + "/accounts/" + ACCOUNT_ID + "/instruments";

    CURL* curl = curl_easy_init();
    if (curl) {
        curl_easy_setopt(curl, CURLOPT_URL, url.c_str());
        curl_easy_setopt(curl, CURLOPT_HTTPHEADER, secureHeader);

        std::string response;
        curl_easy_setopt(curl, CURLOPT_WRITEFUNCTION, WriteCallback);
        curl_easy_setopt(curl, CURLOPT_WRITEDATA, &response);

        CURLcode res = curl_easy_perform(curl);
        long http_code = 0;
        curl_easy_getinfo(curl, CURLINFO_RESPONSE_CODE, &http_code);

        curl_easy_cleanup(curl);

        Json::Value jsonResponse;
        Json::Reader reader;
        reader.parse(response, jsonResponse);

        return std::make_pair(static_cast<int>(http_code), jsonResponse);
    }

    return std::make_pair(0, Json::Value());
}
```

This function uses libcurl to make the HTTP GET request and JsonCpp to parse the JSON response. It returns a pair containing the HTTP status code and the parsed JSON response, similar to the Python version.

