    if (jsonData.isMember(&quot;errorMessage&quot;)) {
        std::cerr &lt;&lt; &quot;API Error: &quot; &lt;&lt; jsonData[&quot;errorMessage&quot;].asString() &lt;&lt; std::endl;
        throw std::runtime_error(&quot;API Error: &quot; + jsonData[&quot;errorMessage&quot;].asString());
